  await cmOriginalPluginOnloadArgsVim.apply(this, args);
  this.commandModeVimrcLintShown = false;
  this.commandModeVimrcExmaps = [];
  this.commandModeVimrcRecursiveMaps = [];
  this.commandModeVimrcFilePath = null;
